CREATE SCHEMA runtime37_test; CREATE SEQUENCE runtime37_test.reached START 1; CREATE TABLE runtime37_test.clock_state(t timestamptz NOT NULL); INSERT INTO runtime37_test.clock_state SELECT date_trunc('day',clock_timestamp() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo'+interval '23 hours 59 minutes 59 seconds';
CREATE FUNCTION runtime37_test.clock_now() RETURNS timestamptz LANGUAGE sql AS $$SELECT t FROM runtime37_test.clock_state$$;
CREATE FUNCTION runtime37_test.probe(label text,legs integer,proofs integer,sealed integer) RETURNS void LANGUAGE plpgsql AS $$ DECLARE nl integer; np integer; ns integer; BEGIN SELECT count(*) INTO nl FROM public.transacoes_caixa t JOIN public.caixa37_pernas p ON p.transacao_id=t.id JOIN public.caixa37_operacoes o ON o.id=p.operacao_id WHERE pg_xact_status(o.xmin::text::xid8)='in progress'; SELECT count(*),count(*) FILTER(WHERE resultado IS NOT NULL) INTO np,ns FROM public.caixa37_operacoes o WHERE pg_xact_status(o.xmin::text::xid8)='in progress'; SELECT count(*) INTO np FROM public.caixa37_pernas p JOIN public.caixa37_operacoes o ON o.id=p.operacao_id WHERE pg_xact_status(o.xmin::text::xid8)='in progress'; IF nl<>legs OR np<>proofs OR ns<>sealed THEN RAISE EXCEPTION 'probe % expected legs/proofs/sealed %/%/% got %/%/%',label,legs,proofs,sealed,nl,np,ns USING ERRCODE='P0002'; END IF; PERFORM nextval('runtime37_test.reached'); END $$;
